window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7c861554c29d33a5"]={"versions": [{"id": "FIG-7c861554c29d33a5", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitätsdiagramm nach der AUTOSAR-Methodik (Methodology Activity Diagram) zur Darstellung des Prozessschritts „Configure Watchdog Manager“. Die Aktivität beschreibt die Konfiguration des Watchdog Managers (Wdm / WdgM) innerhalb der BSW- und ECU-Integrationsphase der AUTOSAR Classic Platform. Sie stellt die Interaktion zwischen der ausführenden Ingenieursrolle, den erforderlichen Eingangsartefakten und dem modifizierten Konfigurationsdatenbestand dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Rolle</strong>:</li>\n<li><code>ECU Integrator</code> (Kardinalität <code>1</code>): Verantwortlicher Bearbeiter, verknüpft über die Relation <code>«performs»</code>.</li>\n<li><strong>Aktivität</strong>:</li>\n<li><code>Configure Watchdog Manager</code>: Zentrale Konfigurationsaufgabe.</li>\n<li><strong>Eingangsartefakte (Eingänge)</strong>:</li>\n<li><code>ECU Extract</code> (Kardinalität <code>1</code>): Verbindliche Systemextraktion für das Steuergerät; Beziehung <code>«input»</code>.</li>\n<li><code>BSW Module Delivered Bundle</code> (Kardinalität <code>0..1</code>): Optionales Lieferpaket von Basissoftware-Modulen mit Modulbeschreibungen; Beziehung <code>«input»</code>.</li>\n<li><code>ECU Timing</code> (Kardinalität <code>0..1</code>): Optionale Timing-Spezifikation (z. B. Deadline-, Alive- und Latenzanforderungen für überwachte Entitäten); Beziehung <code>«input»</code>.</li>\n<li><strong>Ein-/Ausgangsartefakt</strong>:</li>\n<li><code>ECU Configuration Values</code> (Kardinalität <code>1</code>): Repräsentiert die akkumulierte Steuergerätekonfiguration (ARXML), die durch die Aktivität eingelesen und um Watchdog-Manager-Parameter (z. B. Supervised Entities, Checkpoints, Watchdog Modes, Triggering-Intervalle) aktualisiert wird; Beziehung <code>«inoutput»</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der <code>ECU Integrator</code> führt die Aktivität <code>Configure Watchdog Manager</code> durch.</li>\n<li>Als zwingende Vorgabe wird der <code>ECU Extract</code> (Kardinalität 1) herangezogen.</li>\n<li>Sofern vorhanden, werden das <code>BSW Module Delivered Bundle</code> (Kardinalität 0..1) und <code>ECU Timing</code>-Artefakte (Kardinalität 0..1) zur Ableitung von Überwachungszeiträumen und Alive-/Deadline-Parametern konsumiert.</li>\n<li>Die bestehenden <code>ECU Configuration Values</code> werden geladen, die WdgM-spezifischen Konfigurationselemente eingepflegt bzw. angepasst und die aktualisierten Konfigurationswerte in dasselbe Artefakt zurückgeschrieben (<code>«inoutput»</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Verbindlich erforderlich für den Schritt sind der <code>ECU Extract</code> sowie bestehende <code>ECU Configuration Values</code>.</li>\n<li>Das Fehlen von <code>ECU Timing</code> oder <code>BSW Module Delivered Bundle</code> muss vom Konfigurationswerkzeug bzw. Integrator toleriert werden, da beide Artefakte mit der Multiplizität <code>0..1</code> definiert sind.</li>\n<li>Die Inout-Semantik bedingt ein Werkzeugverhalten, das bestehende Konfigurationsparameter anderer BSW-Module in <code>ECU Configuration Values</code> unversehrt belässt und inkrementell anreichert.</li>\n</ul>"}, {"id": "FIG-e6c5058a178ff7a9", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitätsdiagramm nach der AUTOSAR-Methodik (Methodology Activity Diagram) zur Darstellung des Prozessschritts „Configure Watchdog Manager“. Die Aktivität beschreibt die Konfiguration des Watchdog Managers (Wdm / WdgM) innerhalb der BSW- und ECU-Integrationsphase der AUTOSAR Classic Platform. Sie stellt die Interaktion zwischen der ausführenden Ingenieursrolle, den erforderlichen Eingangsartefakten und dem modifizierten Konfigurationsdatenbestand dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Rolle</strong>:</li>\n<li><code>ECU Integrator</code> (Kardinalität <code>1</code>): Verantwortlicher Bearbeiter, verknüpft über die Relation <code>«performs»</code>.</li>\n<li><strong>Aktivität</strong>:</li>\n<li><code>Configure Watchdog Manager</code>: Zentrale Konfigurationsaufgabe.</li>\n<li><strong>Eingangsartefakte (Eingänge)</strong>:</li>\n<li><code>ECU Extract</code> (Kardinalität <code>1</code>): Verbindliche Systemextraktion für das Steuergerät; Beziehung <code>«input»</code>.</li>\n<li><code>BSW Module Delivered Bundle</code> (Kardinalität <code>0..1</code>): Optionales Lieferpaket von Basissoftware-Modulen mit Modulbeschreibungen; Beziehung <code>«input»</code>.</li>\n<li><code>ECU Timing</code> (Kardinalität <code>0..1</code>): Optionale Timing-Spezifikation (z. B. Deadline-, Alive- und Latenzanforderungen für überwachte Entitäten); Beziehung <code>«input»</code>.</li>\n<li><strong>Ein-/Ausgangsartefakt</strong>:</li>\n<li><code>ECU Configuration Values</code> (Kardinalität <code>1</code>): Repräsentiert die akkumulierte Steuergerätekonfiguration (ARXML), die durch die Aktivität eingelesen und um Watchdog-Manager-Parameter (z. B. Supervised Entities, Checkpoints, Watchdog Modes, Triggering-Intervalle) aktualisiert wird; Beziehung <code>«inoutput»</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der <code>ECU Integrator</code> führt die Aktivität <code>Configure Watchdog Manager</code> durch.</li>\n<li>Als zwingende Vorgabe wird der <code>ECU Extract</code> (Kardinalität 1) herangezogen.</li>\n<li>Sofern vorhanden, werden das <code>BSW Module Delivered Bundle</code> (Kardinalität 0..1) und <code>ECU Timing</code>-Artefakte (Kardinalität 0..1) zur Ableitung von Überwachungszeiträumen und Alive-/Deadline-Parametern konsumiert.</li>\n<li>Die bestehenden <code>ECU Configuration Values</code> werden geladen, die WdgM-spezifischen Konfigurationselemente eingepflegt bzw. angepasst und die aktualisierten Konfigurationswerte in dasselbe Artefakt zurückgeschrieben (<code>«inoutput»</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Verbindlich erforderlich für den Schritt sind der <code>ECU Extract</code> sowie bestehende <code>ECU Configuration Values</code>.</li>\n<li>Das Fehlen von <code>ECU Timing</code> oder <code>BSW Module Delivered Bundle</code> muss vom Konfigurationswerkzeug bzw. Integrator toleriert werden, da beide Artefakte mit der Multiplizität <code>0..1</code> definiert sind.</li>\n<li>Die Inout-Semantik bedingt ein Werkzeugverhalten, das bestehende Konfigurationsparameter anderer BSW-Module in <code>ECU Configuration Values</code> unversehrt belässt und inkrementell anreichert.</li>\n</ul>"}], "trans": [{"from": "FIG-7c861554c29d33a5", "to": "FIG-e6c5058a178ff7a9", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
